SELECT COALESCE(SUM(pt.amount), 0)
FROM payment_transaction pt
         JOIN user_card uc ON uc.user_card_id = pt.user_card_id
WHERE uc.user_id = #{userId}
  AND uc.user_card_id = #{cardId}
  AND uc.is_deleted = 0
  AND pt.paid_at >= #{condition.startAt}
  AND pt.paid_at < #{condition.endAt}

SELECT pt.payment_transaction_id,
       s.store_name,
       c.category_name,
       c.category_image_url,
       pt.amount,
       pt.paid_at,
       pt.is_eligible
FROM payment_transaction pt
         JOIN user_card uc ON uc.user_card_id = pt.user_card_id
         LEFT JOIN store s ON s.store_id = pt.store_id
         LEFT JOIN category c ON c.category_id = s.category_id
WHERE uc.user_id = #{userId}
  AND uc.user_card_id = #{cardId}
  AND uc.is_deleted = 0
  AND pt.paid_at >= #{condition.startAt}
  AND pt.paid_at < #{condition.endAt}

  AND (
        pt.paid_at < #{condition.cursorPaidAt}
        OR (
            pt.paid_at = #{condition.cursorPaidAt}
            AND pt.payment_transaction_id < #{condition.cursorTransactionId}
        )
      )

ORDER BY pt.paid_at DESC,
         pt.payment_transaction_id DESC
LIMIT #{condition.limit}

SELECT COALESCE(SUM(CASE WHEN pt.is_eligible = 1 THEN pt.amount ELSE 0 END), 0)
           AS recognized_amount,
       COALESCE(SUM(CASE WHEN pt.is_eligible = 0 THEN pt.amount ELSE 0 END), 0)
           AS excluded_amount
FROM payment_transaction pt
         JOIN user_card uc ON uc.user_card_id = pt.user_card_id
WHERE uc.user_id = #{userId}
  AND uc.user_card_id = #{cardId}
  AND uc.is_deleted = 0
  AND pt.paid_at >= #{condition.startAt}
  AND pt.paid_at < #{condition.endAt}

SELECT is_deleted
FROM user_card
WHERE user_id = #{userId}
  AND card_product_id = #{cardProductId}

mapper.update:
UPDATE user_card
SET is_deleted    = 0,
    first4        = #{request.first4},
    last4         = #{request.last4},
    expiry_date   = #{request.expiryDate},
    display_order = #{displayOrder}
WHERE user_id = #{userId}
  AND card_product_id = #{request.cardProductId}
